// ============================================================================
// LOGO ASSET — HUYANH Natural Rubber (header bộ chứng từ)
// File: src/services/sales/logoAsset.ts  (auto-gen từ src/assets/logo.png → PNG thật)
// Dùng chung: on-screen (<img src={LOGO_DATA_URI}>) + docx (logoUint8Array()).
// ============================================================================
export const LOGO_W = 300
export const LOGO_H = 96
const LOGO_B64 = ""
export const LOGO_DATA_URI = "data:image/png;base64," + LOGO_B64

/** Decode base64 → Uint8Array cho docx ImageRun (chạy trên browser). */
export function logoUint8Array(): Uint8Array {
  const bin = atob(LOGO_B64)
  const arr = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i)
  return arr
}
